"""Hard gate for the LLM ``complete`` tool.

Owns pending-confirmation / ordered-block refusals, skill-level
``complete_when`` condition checks, and skill-run evidence messages for the
injected ``CompletionJudge``. Criteria judging (prompt, LLM, parse) lives on
that collaborator. Internal ``_complete_skill`` / ordered-block ``END`` paths
do not use this gate.
"""

from __future__ import annotations

from collections.abc import Mapping, Sequence
from typing import Any, List, Optional

import structlog

from rasa.agents.core.cancellation import OperationCancelled
from rasa.mantle.orchestration.skill_completion.completion_judge import (
    CompletionJudgeProtocol,
    failed_criteria_lines,
)
from rasa.mantle.orchestration.skill_utils import find_activation_index
from rasa.mantle.orchestration.tool_execution.payload import format_error_as_json
from rasa.mantle.prompts.messages import (
    LlmMessage,
    is_discarded_utterance,
    llm_message,
)
from rasa.mantle.skills.catalog import (
    SkillCatalog,
    is_ordered_block_target_id,
)
from rasa.mantle.skills.conditions import (
    ConditionEvaluationError,
    evaluate_expression,
)
from rasa.mantle.skills.skill import ORDERED_BLOCK_TARGET_ID_SEPARATOR
from rasa.mantle.state.tracker_handle import TrackerHandle
from rasa.shared.constants import ROLE_ASSISTANT, ROLE_USER
from rasa.shared.core.events import (
    BotUttered,
    Event,
    ToolExecuted,
    UserUttered,
)

structlogger = structlog.get_logger()

# Conversation-turn cap for completion-judge evidence (user + following bot
# replies = one turn). Separate from prompt-history DEFAULT_MAX_UTTERANCES so
# multi-bubble bot replies do not silently expand judge cost/latency.
DEFAULT_MAX_COMPLETION_JUDGE_TURNS = 7


class SkillCompletionGate:
    """Collaborator that refuses LLM ``complete`` when exit is not allowed."""

    def __init__(
        self,
        skill_catalog: SkillCatalog,
        completion_judge: Optional[CompletionJudgeProtocol] = None,
    ) -> None:
        self._skill_catalog = skill_catalog
        self._completion_judge = completion_judge

    def set_completion_judge(self, completion_judge: CompletionJudgeProtocol) -> None:
        """Inject the orchestrator-owned completion-criteria judge."""
        self._completion_judge = completion_judge

    async def refuse_complete_tool(
        self,
        tracker_handle: TrackerHandle,
        memory_values: Mapping[str, Any],
    ) -> Optional[str]:
        """Gate the LLM ``complete`` tool; return error JSON or ``None``.

        Does not run for block ``END`` / internal ``_complete_skill`` callers.
        """
        pending_error = self._refused_for_pending_confirmation(tracker_handle)
        if pending_error is not None:
            return format_error_as_json(pending_error)

        block_error = self._refused_in_ordered_block(tracker_handle)
        if block_error is not None:
            return format_error_as_json(block_error)

        unmet = self._unmet_complete_when_conditions(tracker_handle, memory_values)
        # Skip the criteria judge when the memory condition already fails — an
        # extra LLM call is unnecessary to refuse, and voice latency matters.
        if unmet:
            return format_error_as_json(
                format_complete_gate_error(unmet_conditions=unmet)
            )

        failed_criteria = await self._failed_complete_when_criteria(tracker_handle)
        if failed_criteria:
            skill_id, _ = tracker_handle.memory_scope()
            structlogger.debug(
                "mantle.skill_completion_gate.criteria_unmet",
                skill_id=skill_id,
                failed_count=len(failed_criteria),
                failed_criteria=[
                    {"criterion": criterion, "reasoning": reason}
                    for criterion, reason in failed_criteria
                ],
            )
            return format_error_as_json(
                format_complete_gate_error(failed_criteria=failed_criteria)
            )
        return None

    def build_skill_run_evidence_messages(
        self, tracker_handle: TrackerHandle
    ) -> List[LlmMessage]:
        """Build chat-role evidence from events since this skill's entry.

        Caps evidence to the newest :data:`DEFAULT_MAX_COMPLETION_JUDGE_TURNS`
        conversation turns — one user message plus its following bot replies
        counts as one turn (multiple ``BotUttered`` in the same reply do not
        each burn a slot). Leading bot-only content before the first in-skill
        user message counts as its own turn. Tool events that fall inside the
        retained turns are kept. Consecutive same-role turns are merged.

        Newlines in event text are collapsed so payloads cannot forge extra
        chat turns via embedded role markers.
        """
        events = _window_skill_run_events_for_transcript(
            self._skill_run_history_events(tracker_handle)
        )
        messages: List[LlmMessage] = []
        for event in events:
            role_and_content = _evidence_role_and_content(event)
            if role_and_content is None:
                continue
            role, content = role_and_content
            if not content:
                continue
            if messages and messages[-1]["role"] == role:
                previous = messages[-1].get("content") or ""
                messages[-1] = llm_message(role, f"{previous}\n{content}")
            else:
                messages.append(llm_message(role, content))
        return messages

    def _refused_for_pending_confirmation(
        self,
        tracker_handle: TrackerHandle,
    ) -> Optional[str]:
        """Refuse when the active frame still awaits tool confirmation."""
        pending = tracker_handle.pending_tool_confirmation_for_active_frame()
        if pending is None:
            return None
        return (
            "Cannot complete skill while tool confirmation is pending for "
            f"'{pending.tool_name}'. Call @tool.resolve_tool_confirmation first."
        )

    def _refused_in_ordered_block(
        self,
        tracker_handle: TrackerHandle,
    ) -> Optional[str]:
        """Refuse when the top frame is an ordered block of the active skill."""
        skill_id, flow_id = tracker_handle.memory_scope()
        if not skill_id or not flow_id:
            return None
        if not is_ordered_block_target_id(skill_id, flow_id):
            return None
        prefix = f"{skill_id}{ORDERED_BLOCK_TARGET_ID_SEPARATOR}"
        block_id = flow_id[len(prefix) :] if flow_id.startswith(prefix) else flow_id
        return f"Cannot complete skill while ordered block '{block_id}' is in progress."

    def _unmet_complete_when_conditions(
        self,
        tracker_handle: TrackerHandle,
        memory_values: Mapping[str, Any],
    ) -> list[str]:
        """Return the skill-level ``complete_when.condition`` when it is not true."""
        skill_id, _ = tracker_handle.memory_scope()
        if not skill_id:
            return []
        skill = self._skill_catalog.skill_by_id(skill_id)
        if skill is None or skill.complete_when is None:
            return []
        condition = skill.complete_when.condition
        if not condition:
            return []
        try:
            if evaluate_expression(condition, dict(memory_values)):
                return []
        except ConditionEvaluationError:
            pass
        return [condition]

    async def _failed_complete_when_criteria(
        self,
        tracker_handle: TrackerHandle,
    ) -> list[tuple[str, str]]:
        """Run the completion judge when criteria are authored; fail closed."""
        skill_id, _ = tracker_handle.memory_scope()
        if not skill_id:
            return []
        skill = self._skill_catalog.skill_by_id(skill_id)
        if skill is None or skill.complete_when is None:
            return []
        criteria = skill.complete_when.criteria
        if not criteria:
            return []
        if self._completion_judge is None:
            return [
                (criterion, "Completion judge is not configured.")
                for criterion in criteria
            ]
        evidence = self.build_skill_run_evidence_messages(tracker_handle)
        try:
            verdicts = await self._completion_judge.judge(criteria, evidence)
        except OperationCancelled:
            raise
        except Exception as exc:
            structlogger.warning(
                "mantle.skill_completion_gate.completion_judge_error",
                error=str(exc),
                error_type=type(exc).__name__,
                skill_id=skill_id,
            )
            return [
                (criterion, "Completion judge failed; cannot verify criterion.")
                for criterion in criteria
            ]
        if len(verdicts) != len(criteria):
            return [
                (
                    criterion,
                    "Completion judge returned an incomplete verdict list.",
                )
                for criterion in criteria
            ]
        return failed_criteria_lines(verdicts)

    def _skill_run_history_events(self, tracker_handle: TrackerHandle) -> list[Event]:
        """Events from the current skill's ``SkillActivated`` through now.

        When no matching ``SkillActivated`` exists, returns an empty list so
        pre-skill turns cannot enter the completion-judge transcript.
        """
        events = list(tracker_handle.tracker.events)
        skill_id, _ = tracker_handle.memory_scope()
        if not skill_id:
            return events
        start = find_activation_index(events, skill_id=skill_id)
        if start is None:
            structlogger.warning(
                "mantle.skill_completion_gate.missing_skill_activated",
                skill_id=skill_id,
                event_count=len(events),
            )
            return []
        return events[start:]


def format_complete_gate_error(
    *,
    unmet_conditions: Sequence[str] = (),
    failed_criteria: Sequence[tuple[str, str]] = (),
) -> str:
    """Stable multi-line refuse message for unmet completion requirements.

    Failed criteria include only the authored criterion text — not judge
    ``reasoning`` — so user-influenced judge prose does not re-enter the
    orchestrator LLM via the tool error.
    """
    lines = ["Cannot complete skill yet."]
    for condition in unmet_conditions:
        lines.append(f"- condition: {condition}")
    for criterion, _reason in failed_criteria:
        lines.append(f"- criterion: {criterion}")
    return "\n".join(lines)


def _sanitize_transcript_line_text(text: str) -> str:
    """Collapse CR/LF so event payloads cannot forge transcript role lines."""
    return " ".join(text.replace("\r", "\n").splitlines()).strip()


def _evidence_role_and_content(event: Event) -> tuple[str, str] | None:
    """Map one tracker event to a judge evidence role and content, or skip."""
    if isinstance(event, (UserUttered, BotUttered)) and is_discarded_utterance(event):
        # Incoming-message fallback bot replies are also stamped discarded so
        # they do not enter judge evidence or concatenate onto a prior assistant
        # turn.
        return None
    if isinstance(event, UserUttered) and event.text:
        return ROLE_USER, _sanitize_transcript_line_text(event.text)
    if isinstance(event, BotUttered) and event.text:
        return ROLE_ASSISTANT, _sanitize_transcript_line_text(event.text)
    if isinstance(event, ToolExecuted):
        result = event.result if isinstance(event.result, str) else ""
        preview = result if len(result) <= 240 else f"{result[:237]}..."
        preview = _sanitize_transcript_line_text(preview)
        tool_name = _sanitize_transcript_line_text(event.tool_name)
        return ROLE_USER, f"tool: {tool_name} -> {preview}"
    return None


def _conversation_turn_start_indexes(events: list[Event]) -> list[int]:
    """Return indexes where each completion-judge conversation turn begins.

    A turn is one ``UserUttered`` plus any following ``BotUttered`` until the
    next user message. Leading bot content before the first in-window user
    message forms its own turn starting at event 0 so preceding tool evidence
    stays attached.
    """
    user_starts = [
        index
        for index, event in enumerate(events)
        if isinstance(event, UserUttered)
        and event.text
        and not is_discarded_utterance(event)
    ]
    leading_bot_before_user = any(
        isinstance(event, BotUttered)
        and event.text
        and not is_discarded_utterance(event)
        for event in (events[: user_starts[0]] if user_starts else events)
    )
    if leading_bot_before_user:
        return [0, *user_starts]
    return user_starts


def _window_skill_run_events_for_transcript(events: list[Event]) -> list[Event]:
    """Keep events from the oldest retained conversation turn through the end.

    Caps by conversation turns (user + following bot replies), not by raw
    utterance events, so multi-bubble bot replies do not shrink the window
    faster than dialogue turns.
    """
    turn_starts = _conversation_turn_start_indexes(events)
    if len(turn_starts) <= DEFAULT_MAX_COMPLETION_JUDGE_TURNS:
        return events
    return events[turn_starts[-DEFAULT_MAX_COMPLETION_JUDGE_TURNS] :]
